1	package filter
2	
3	import (
4		"time"
5	
6		"github.com/pkg/errors"
7		exprv1 "google.golang.org/genproto/googleapis/api/expr/v1alpha1"
8	)
9	
10	// parseContext carries the schema plus the frozen evaluation time used to fold
11	// the `now` variable into a constant. Freezing once per compile guarantees a
12	// single filter observes a single instant.
13	type parseContext struct {
14		schema Schema
15		now    time.Time
16	}
17	
18	func buildCondition(expr *exprv1.Expr, pc parseContext) (Condition, error) {
19		switch v := expr.ExprKind.(type) {
20		case *exprv1.Expr_CallExpr:
21			return buildCallCondition(v.CallExpr, pc)
22		case *exprv1.Expr_ConstExpr:
23			val, err := getConstValue(expr)
24			if err != nil {
25				return nil, err
26			}
27			if v, ok := val.(bool); ok {
28				return &ConstantCondition{Value: v}, nil
29			}
30			return nil, errors.New("filter must evaluate to a boolean value")
31		case *exprv1.Expr_IdentExpr:
32			name := v.IdentExpr.GetName()
33			field, ok := pc.schema.Field(name)
34			if !ok {
35				return nil, errors.Errorf("unknown identifier %q", name)
36			}
37			if field.Type != FieldTypeBool {
38				return nil, errors.Errorf("identifier %q is not boolean", name)
39			}
40			return &FieldPredicateCondition{Field: name}, nil
41		case *exprv1.Expr_ComprehensionExpr:
42			return buildComprehensionCondition(v.ComprehensionExpr, pc.schema)
43		default:
44			return nil, errors.New("unsupported top-level expression")
45		}
46	}
47	
48	func buildCallCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
49		switch call.Function {
50		case "_&&_":
51			if len(call.Args) != 2 {
52				return nil, errors.New("logical AND expects two arguments")
53			}
54			left, err := buildCondition(call.Args[0], pc)
55			if err != nil {
56				return nil, err
57			}
58			right, err := buildCondition(call.Args[1], pc)
59			if err != nil {
60				return nil, err
61			}
62			return &LogicalCondition{
63				Operator: LogicalAnd,
64				Left:     left,
65				Right:    right,
66			}, nil
67		case "_||_":
68			if len(call.Args) != 2 {
69				return nil, errors.New("logical OR expects two arguments")
70			}
71			left, err := buildCondition(call.Args[0], pc)
72			if err != nil {
73				return nil, err
74			}
75			right, err := buildCondition(call.Args[1], pc)
76			if err != nil {
77				return nil, err
78			}
79			return &LogicalCondition{
80				Operator: LogicalOr,
81				Left:     left,
82				Right:    right,
83			}, nil
84		case "!_":
85			if len(call.Args) != 1 {
86				return nil, errors.New("logical NOT expects one argument")
87			}
88			child, err := buildCondition(call.Args[0], pc)
89			if err != nil {
90				return nil, err
91			}
92			return &NotCondition{Expr: child}, nil
93		case "_==_", "_!=_", "_<_", "_>_", "_<=_", "_>=_":
94			return buildComparisonCondition(call, pc)
95		case "@in":
96			return buildInCondition(call, pc)
97		case "contains":
98			return buildTextMatchCondition(call, pc.schema, TextMatchContains)
99		case "startsWith":
100			return buildTextMatchCondition(call, pc.schema, TextMatchPrefix)
101		case "endsWith":
102			return buildTextMatchCondition(call, pc.schema, TextMatchSuffix)
103		case "matches":
104			return buildMatchesCondition(call, pc.schema)
105		case "sets.contains", "sets.intersects", "sets.equivalent":
106			return buildSetCondition(call, pc)
107		default:
108			val, ok, err := evaluateBool(call)
109			if err != nil {
110				return nil, err
111			}
112			if ok {
113				return &ConstantCondition{Value: val}, nil
114			}
115			return nil, errors.Errorf("unsupported call expression %q", call.Function)
116		}
117	}
118	
119	func buildComparisonCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
120		if len(call.Args) != 2 {
121			return nil, errors.New("comparison expects two arguments")
122		}
123		op, err := toComparisonOperator(call.Function)
124		if err != nil {
125			return nil, err
126		}
127	
128		left, err := buildValueExpr(call.Args[0], pc)
129		if err != nil {
130			return nil, err
131		}
132		right, err := buildValueExpr(call.Args[1], pc)
133		if err != nil {
134			return nil, err
135		}
136	
137		// The renderer expects a field/function/accessor on the left. A folded
138		// literal on the left (e.g. now.getMonth() == created_ts.getMonth()) swaps
139		// operands; two literals fold to a constant outcome.
140		if leftLit, ok := left.(*LiteralValue); ok {
141			if rightLit, ok := right.(*LiteralValue); ok {
142				outcome, err := compareLiterals(leftLit.Value, op, rightLit.Value)
143				if err != nil {
144					return nil, err
145				}
146				return &ConstantCondition{Value: outcome}, nil
147			}
148			left, right = right, left
149			op = mirrorComparisonOperator(op)
150		}
151	
152		// If the left side is a field, validate allowed operators.
153		if field, ok := left.(*FieldRef); ok {
154			def, exists := pc.schema.Field(field.Name)
155			if !exists {
156				return nil, errors.Errorf("unknown identifier %q", field.Name)
157			}
158			if def.Kind == FieldKindVirtualAlias {
159				def, exists = pc.schema.ResolveAlias(field.Name)
160				if !exists {
161					return nil, errors.Errorf("invalid alias %q", field.Name)
162				}
163			}
164			if def.AllowedComparisonOps != nil {
165				if _, allowed := def.AllowedComparisonOps[op]; !allowed {
166					return nil, errors.Errorf("operator %s not allowed for field %q", op, field.Name)
167				}
168			}
169		}
170	
171		return &ComparisonCondition{
172			Left:     left,
173			Operator: op,
174			Right:    right,
175		}, nil
176	}
177	
178	// mirrorComparisonOperator flips an operator so swapped operands keep the
179	// original meaning (a < b ⇔ b > a).
180	func mirrorComparisonOperator(op ComparisonOperator) ComparisonOperator {
181		switch op {
182		case CompareLt:
183			return CompareGt
184		case CompareLte:
185			return CompareGte
186		case CompareGt:
187			return CompareLt
188		case CompareGte:
189			return CompareLte
190		default:
191			return op
192		}
193	}
194	
195	// compareLiterals evaluates a comparison whose operands both folded to
196	// constants (e.g. now.getFullYear() >= 2026) into a boolean outcome.
197	func compareLiterals(left any, op ComparisonOperator, right any) (bool, error) {
198		if l, r, ok := asFloats(left, right); ok {
199			switch op {
200			case CompareEq:
201				return l == r, nil
202			case CompareNeq:
203				return l != r, nil
204			case CompareLt:
205				return l < r, nil
206			case CompareLte:
207				return l <= r, nil
208			case CompareGt:
209				return l > r, nil
210			case CompareGte:
211				return l >= r, nil
212			}
213		}
214		if l, ok := left.(string); ok {
215			if r, ok := right.(string); ok {
216				switch op {
217				case CompareEq:
218					return l == r, nil
219				case CompareNeq:
220					return l != r, nil
221				case CompareLt:
222					return l < r, nil
223				case CompareLte:
224					return l <= r, nil
225				case CompareGt:
226					return l > r, nil
227				case CompareGte:
228					return l >= r, nil
229				}
230			}
231		}
232		if l, ok := left.(bool); ok {
233			if r, ok := right.(bool); ok {
234				switch op {
235				case CompareEq:
236					return l == r, nil
237				case CompareNeq:
238					return l != r, nil
239				}
240			}
241		}
242		return false, errors.Errorf("unsupported constant comparison %T %s %T", left, op, right)
243	}
244	
245	// asFloats widens both operands to float64 when each is numeric.
246	func asFloats(left, right any) (float64, float64, bool) {
247		l, lok := toFloat(left)
248		r, rok := toFloat(right)
249		return l, r, lok && rok
250	}
251	
252	func toFloat(v any) (float64, bool) {
253		switch x := v.(type) {
254		case int64:
255			return float64(x), true
256		case float64:
257			return x, true
258		}
259		return 0, false
260	}
261	
262	func buildInCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
263		if len(call.Args) != 2 {
264			return nil, errors.New("in operator expects two arguments")
265		}
266	
267		// Handle identifier in list syntax.
268		if identName, err := getIdentName(call.Args[0]); err == nil {
269			if field, ok := pc.schema.Field(identName); ok && field.Kind == FieldKindVirtualAlias {
270				if _, aliasOk := pc.schema.ResolveAlias(identName); !aliasOk {
271					return nil, errors.Errorf("invalid alias %q", identName)
272				}
273			} else if !ok {
274				return nil, errors.Errorf("unknown identifier %q", identName)
275			}
276	
277			if listExpr := call.Args[1].GetListExpr(); listExpr != nil {
278				values := make([]ValueExpr, 0, len(listExpr.Elements))
279				for _, element := range listExpr.Elements {
280					value, err := buildValueExpr(element, pc)
281					if err != nil {
282						return nil, err
283					}
284					values = append(values, value)
285				}
286				return &InCondition{
287					Left:   &FieldRef{Name: identName},
288					Values: values,
289				}, nil
290			}
291		}
292	
293		// Handle "value in identifier" syntax.
294		if identName, err := getIdentName(call.Args[1]); err == nil {
295			if _, ok := pc.schema.Field(identName); !ok {
296				return nil, errors.Errorf("unknown identifier %q", identName)
297			}
298			element, err := buildValueExpr(call.Args[0], pc)
299			if err != nil {
300				return nil, err
301			}
302			return &ElementInCondition{
303				Element: element,
304				Field:   identName,
305			}, nil
306		}
307	
308		return nil, errors.New("invalid use of in operator")
309	}
