378	func buildValueExpr(expr *exprv1.Expr, pc parseContext) (ValueExpr, error) {
379		if identName, err := getIdentName(expr); err == nil {
380			// `now` is not a schema field; it folds to the frozen evaluation time.
381			if identName == "now" {
382				return &LiteralValue{Value: pc.now.Unix()}, nil
383			}
384			if _, ok := pc.schema.Field(identName); !ok {
385				return nil, errors.Errorf("unknown identifier %q", identName)
386			}
387			return &FieldRef{Name: identName}, nil
388		}
389	
390		if literal, err := getConstValue(expr); err == nil {
391			return &LiteralValue{Value: literal}, nil
392		}
393	
394		if value, ok, err := evaluateNumeric(expr, pc.now); err != nil {
395			return nil, err
396		} else if ok {
397			return &LiteralValue{Value: value}, nil
398		}
399	
400		if boolVal, ok, err := evaluateBoolExpr(expr); err != nil {
401			return nil, err
402		} else if ok {
403			return &LiteralValue{Value: boolVal}, nil
404		}
405	
406		if call := expr.GetCallExpr(); call != nil {
407			if call.Target != nil && isTimestampAccessor(call.Function) {
408				return buildTimestampAccessor(call, pc)
409			}
410			switch call.Function {
411			case "size":
412				if len(call.Args) != 1 {
413					return nil, errors.New("size() expects one argument")
414				}
415				arg, err := buildValueExpr(call.Args[0], pc)
416				if err != nil {
417					return nil, err
418				}
419				return &FunctionValue{
420					Name: "size",
421					Args: []ValueExpr{arg},
422				}, nil
423			case "_+_", "_-_", "_*_":
424				value, ok, err := evaluateNumeric(expr, pc.now)
425				if err != nil {
426					return nil, err
427				}
428				if ok {
429					return &LiteralValue{Value: value}, nil
430				}
431			default:
432				// Fall through to error return below
433			}
434		}
435	
436		return nil, errors.New("unsupported value expression")
437	}
438	
439	func toComparisonOperator(fn string) (ComparisonOperator, error) {
440		switch fn {
441		case "_==_":
442			return CompareEq, nil
443		case "_!=_":
444			return CompareNeq, nil
445		case "_<_":
446			return CompareLt, nil
447		case "_>_":
448			return CompareGt, nil
449		case "_<=_":
450			return CompareLte, nil
451		case "_>=_":
452			return CompareGte, nil
453		default:
454			return "", errors.Errorf("unsupported comparison operator %q", fn)
455		}
456	}
457	
458	func getIdentName(expr *exprv1.Expr) (string, error) {
459		if ident := expr.GetIdentExpr(); ident != nil {
460			return ident.GetName(), nil
461		}
462		return "", errors.New("expression is not an identifier")
463	}
464	
465	func getConstValue(expr *exprv1.Expr) (interface{}, error) {
466		v, ok := expr.ExprKind.(*exprv1.Expr_ConstExpr)
467		if !ok {
468			return nil, errors.New("expression is not a literal")
469		}
470		switch x := v.ConstExpr.ConstantKind.(type) {
471		case *exprv1.Constant_StringValue:
472			return v.ConstExpr.GetStringValue(), nil
473		case *exprv1.Constant_Int64Value:
474			return v.ConstExpr.GetInt64Value(), nil
475		case *exprv1.Constant_Uint64Value:
476			return int64(v.ConstExpr.GetUint64Value()), nil
477		case *exprv1.Constant_DoubleValue:
478			return v.ConstExpr.GetDoubleValue(), nil
479		case *exprv1.Constant_BoolValue:
480			return v.ConstExpr.GetBoolValue(), nil
481		case *exprv1.Constant_NullValue:
482			return nil, nil
483		default:
484			return nil, errors.Errorf("unsupported constant %T", x)
485		}
486	}
487	
488	func evaluateBool(call *exprv1.Expr_Call) (bool, bool, error) {
489		val, ok, err := evaluateBoolExpr(&exprv1.Expr{ExprKind: &exprv1.Expr_CallExpr{CallExpr: call}})
490		return val, ok, err
491	}
492	
493	func evaluateBoolExpr(expr *exprv1.Expr) (bool, bool, error) {
494		if literal, err := getConstValue(expr); err == nil {
495			if b, ok := literal.(bool); ok {
496				return b, true, nil
497			}
498			return false, false, nil
499		}
500		if call := expr.GetCallExpr(); call != nil && call.Function == "!_" {
501			if len(call.Args) != 1 {
502				return false, false, errors.New("NOT expects exactly one argument")
503			}
504			val, ok, err := evaluateBoolExpr(call.Args[0])
505			if err != nil || !ok {
506				return false, false, err
507			}
508			return !val, true, nil
509		}
510		return false, false, nil
511	}
512	
513	// evaluateNumeric constant-folds an expression to an int64 measured in seconds:
514	// timestamps and `now` fold to Unix epoch seconds, durations fold to a number of
515	// seconds, and the two combine through standard arithmetic. CEL has already
516	// type-checked the operand combinations, so the folded int math is well-formed.
517	func evaluateNumeric(expr *exprv1.Expr, now time.Time) (int64, bool, error) {
518		if literal, err := getConstValue(expr); err == nil {
519			switch v := literal.(type) {
520			case int64:
521				return v, true, nil
522			case float64:
523				return int64(v), true, nil
524			}
525			return 0, false, nil
526		}
527	
528		// The `now` variable folds to the frozen evaluation time.
529		if ident := expr.GetIdentExpr(); ident != nil {
530			if ident.GetName() == "now" {
531				return now.Unix(), true, nil
532			}
533			return 0, false, nil
534		}
535	
536		call := expr.GetCallExpr()
537		if call == nil {
538			return 0, false, nil
539		}
540	
541		switch call.Function {
542		case "timestamp":
543			return evaluateTimestamp(call)
544		case "duration":
545			return evaluateDuration(call)
546		case "_+_", "_-_", "_*_", "_/_", "_%_":
547			if len(call.Args) != 2 {
548				return 0, false, errors.New("arithmetic requires two arguments")
549			}
550			left, ok, err := evaluateNumeric(call.Args[0], now)
551			if err != nil {
552				return 0, false, err
553			}
554			if !ok {
555				return 0, false, nil
556			}
557			right, ok, err := evaluateNumeric(call.Args[1], now)
558			if err != nil {
559				return 0, false, err
560			}
561			if !ok {
562				return 0, false, nil
563			}
564			switch call.Function {
565			case "_+_":
566				return left + right, true, nil
567			case "_-_":
568				return left - right, true, nil
569			case "_*_":
570				return left * right, true, nil
571			case "_/_":
572				if right == 0 {
573					return 0, false, errors.New("division by zero")
574				}
575				return left / right, true, nil
576			case "_%_":
577				if right == 0 {
578					return 0, false, errors.New("modulo by zero")
579				}
580				return left % right, true, nil
581			default:
582				return 0, false, errors.Errorf("unsupported arithmetic operator %q", call.Function)
583			}
584		default:
585			return 0, false, nil
586		}
587	}
588	
589	// evaluateTimestamp folds timestamp("RFC3339") and timestamp(<epoch int>) into
590	// Unix epoch seconds.
591	func evaluateTimestamp(call *exprv1.Expr_Call) (int64, bool, error) {
592		if len(call.Args) != 1 {
593			return 0, false, errors.New("timestamp() expects one argument")
594		}
595		value, err := getConstValue(call.Args[0])
596		if err != nil {
597			return 0, false, errors.Wrap(err, "timestamp() only supports literal arguments")
598		}
599		switch v := value.(type) {
600		case string:
601			ts, err := time.Parse(time.RFC3339, v)
602			if err != nil {
603				return 0, false, errors.Wrap(err, "invalid timestamp literal")
604			}
605			return ts.Unix(), true, nil
606		case int64:
607			return v, true, nil
608		default:
609			return 0, false, errors.New("timestamp() argument must be an RFC3339 string or epoch int")
610		}
611	}
612	
613	// evaluateDuration folds duration("<go-duration>") into a number of seconds.
614	func evaluateDuration(call *exprv1.Expr_Call) (int64, bool, error) {
615		if len(call.Args) != 1 {
616			return 0, false, errors.New("duration() expects one argument")
617		}
618		value, err := getConstValue(call.Args[0])
619		if err != nil {
620			return 0, false, errors.Wrap(err, "duration() only supports literal arguments")
621		}
622		str, ok := value.(string)
623		if !ok {
624			return 0, false, errors.New("duration() argument must be a string")
625		}
626		d, err := time.ParseDuration(str)
627		if err != nil {
628			return 0, false, errors.Wrap(err, "invalid duration literal")
629		}
630		return int64(d.Seconds()), true, nil
631	}
632	
633	// timestampAccessors is the set of supported CEL timestamp accessor methods.
634	var timestampAccessors = map[string]bool{
635		"getFullYear":   true,
636		"getMonth":      true,
637		"getDate":       true,
638		"getDayOfMonth": true,
639		"getDayOfWeek":  true,
640		"getDayOfYear":  true,
641		"getHours":      true,
642		"getMinutes":    true,
643		"getSeconds":    true,
644	}
645	
646	func isTimestampAccessor(name string) bool {
647		return timestampAccessors[name]
648	}
649	
650	// buildTimestampAccessor converts created_ts.getMonth() into a FieldAccessorValue.
651	// A `now` target folds to a literal date part of the frozen evaluation time, so
652	// expressions like created_ts.getMonth() == now.getMonth() stay dynamic per compile.
653	// Timezone arguments are rejected; extraction is UTC (see renderer).
654	func buildTimestampAccessor(call *exprv1.Expr_Call, pc parseContext) (ValueExpr, error) {
655		targetName, err := getIdentName(call.Target)
656		if err != nil {
657			return nil, errors.Wrap(err, "timestamp accessor requires a field target")
658		}
659		if len(call.Args) != 0 {
660			return nil, errors.Errorf("%s() with a timezone argument is not supported", call.Function)
661		}
662		if targetName == "now" {
663			return &LiteralValue{Value: foldNowAccessor(call.Function, pc.now)}, nil
664		}
665		field, ok := pc.schema.Field(targetName)
666		if !ok {
667			return nil, errors.Errorf("unknown identifier %q", targetName)
668		}
669		if field.Type != FieldTypeTimestamp {
670			return nil, errors.Errorf("%s() is only valid on timestamp fields, got %q", call.Function, targetName)
671		}
672		return &FieldAccessorValue{Field: targetName, Accessor: call.Function}, nil
673	}
674	
675	// foldNowAccessor evaluates a timestamp accessor against the frozen evaluation
676	// time in UTC, matching CEL result bases (0-based month, day-of-month, day-of-week
677	// with 0 = Sunday, and day-of-year; 1-based getDate).
678	func foldNowAccessor(accessor string, now time.Time) int64 {
679		t := now.UTC()
680		switch accessor {
681		case "getFullYear":
682			return int64(t.Year())
683		case "getMonth":
684			return int64(t.Month()) - 1
685		case "getDate":
686			return int64(t.Day())
687		case "getDayOfMonth":
688			return int64(t.Day()) - 1
689		case "getDayOfWeek":
690			return int64(t.Weekday())
691		case "getDayOfYear":
692			return int64(t.YearDay()) - 1
693		case "getHours":
694			return int64(t.Hour())
695		case "getMinutes":
696			return int64(t.Minute())
697		case "getSeconds":
698			return int64(t.Second())
699		}
700		return 0
701	}
702	
703	// buildSetCondition desugars ext.Sets() operations over a JSON list field into
704	// existing IR: membership reduces to ElementInCondition, and equivalence adds a
705	// length check. This relies on the list field being a set (no duplicates), which
706	// holds for memo tags.
707	func buildSetCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
708		if len(call.Args) != 2 {
709			return nil, errors.Errorf("%s expects two arguments", call.Function)
710		}
711	
712		fieldName, err := getIdentName(call.Args[0])
713		if err != nil {
714			return nil, errors.Wrap(err, "set operations require a list field as the first argument")
715		}
716		field, ok := pc.schema.Field(fieldName)
717		if !ok {
718			return nil, errors.Errorf("unknown identifier %q", fieldName)
719		}
720		if field.Kind != FieldKindJSONList {
721			return nil, errors.Errorf("set operations require a list field, got %q", fieldName)
722		}
723	
724		listExpr := call.Args[1].GetListExpr()
725		if listExpr == nil {
726			return nil, errors.New("set operations require a list literal as the second argument")
727		}
728		values := make([]string, 0, len(listExpr.Elements))
729		for _, el := range listExpr.Elements {
730			v, err := getConstValue(el)
731			if err != nil {
732				return nil, errors.Wrap(err, "set operations only support literal string elements")
733			}
734			s, ok := v.(string)
735			if !ok {
736				return nil, errors.New("set operations require string elements")
737			}
738			values = append(values, s)
739		}
740	
741		membership := func(s string) Condition {
742			return &ElementInCondition{Element: &LiteralValue{Value: s}, Field: fieldName}
743		}
744		sizeEquals := func(n int) Condition {
745			return &ComparisonCondition{
746				Left:     &FunctionValue{Name: "size", Args: []ValueExpr{&FieldRef{Name: fieldName}}},
747				Operator: CompareEq,
748				Right:    &LiteralValue{Value: int64(n)},
749			}
750		}
751	
752		switch call.Function {
753		case "sets.contains":
754			if len(values) == 0 {
755				return &ConstantCondition{Value: true}, nil
756			}
757			return combineConditions(LogicalAnd, mapConditions(values, membership)), nil
758		case "sets.intersects":
759			if len(values) == 0 {
760				return &ConstantCondition{Value: false}, nil
761			}
762			return combineConditions(LogicalOr, mapConditions(values, membership)), nil
763		case "sets.equivalent":
764			distinct := distinctStrings(values)
765			if len(distinct) == 0 {
766				return sizeEquals(0), nil
767			}
768			contains := combineConditions(LogicalAnd, mapConditions(distinct, membership))
769			return &LogicalCondition{Operator: LogicalAnd, Left: contains, Right: sizeEquals(len(distinct))}, nil
770		default:
771			return nil, errors.Errorf("unsupported set operation %q", call.Function)
772		}
773	}
774	
775	func mapConditions(values []string, f func(string) Condition) []Condition {
776		conds := make([]Condition, 0, len(values))
777		for _, v := range values {
778			conds = append(conds, f(v))
779		}
780		return conds
781	}
782	
783	func combineConditions(op LogicalOperator, conds []Condition) Condition {
784		result := conds[0]
785		for _, c := range conds[1:] {
786			result = &LogicalCondition{Operator: op, Left: result, Right: c}
787		}
788		return result
789	}
790	
791	func distinctStrings(values []string) []string {
792		seen := make(map[string]bool, len(values))
793		out := make([]string, 0, len(values))
794		for _, v := range values {
795			if !seen[v] {
796				seen[v] = true
797				out = append(out, v)
798			}
799		}
800		return out
801	}
802	
803	// buildComprehensionCondition handles CEL comprehension expressions (exists, all, etc.).
804	func buildComprehensionCondition(comp *exprv1.Expr_Comprehension, schema Schema) (Condition, error) {
805		// Determine the comprehension kind by examining the loop initialization and step
806		kind, err := detectComprehensionKind(comp)
807		if err != nil {
808			return nil, err
809		}
810	
811		// Get the field being iterated over
812		iterRangeIdent := comp.IterRange.GetIdentExpr()
813		if iterRangeIdent == nil {
814			return nil, errors.New("comprehension range must be a field identifier")
815		}
816		fieldName := iterRangeIdent.GetName()
817	
818		// Validate the field
819		field, ok := schema.Field(fieldName)
820		if !ok {
821			return nil, errors.Errorf("unknown field %q in comprehension", fieldName)
822		}
823		if field.Kind != FieldKindJSONList {
824			return nil, errors.Errorf("field %q does not support comprehension (must be a list)", fieldName)
825		}
826	
827		// Extract the predicate from the loop step
828		predicate, err := extractPredicate(comp, schema)
829		if err != nil {
830			return nil, err
831		}
832	
833		return &ListComprehensionCondition{
834			Kind:      kind,
835			Field:     fieldName,
836			IterVar:   comp.IterVar,
837			Predicate: predicate,
838		}, nil
839	}
840	
841	// detectComprehensionKind determines if this is an exists() macro.
842	// Only exists() is currently supported.
843	func detectComprehensionKind(comp *exprv1.Expr_Comprehension) (ComprehensionKind, error) {
844		// Check the accumulator initialization
845		accuInit := comp.AccuInit.GetConstExpr()
846		if accuInit == nil {
847			return "", errors.New("comprehension accumulator must be initialized with a constant")
848		}
849	
850		// exists() starts with false and uses OR (||) in loop step
851		if !accuInit.GetBoolValue() {
852			if step := comp.LoopStep.GetCallExpr(); step != nil && step.Function == "_||_" {
853				return ComprehensionExists, nil
854			}
855		}
856	
857		// all() starts with true and uses AND (&&) in the loop step.
858		if accuInit.GetBoolValue() {
859			if step := comp.LoopStep.GetCallExpr(); step != nil && step.Function == "_&&_" {
860				return ComprehensionAll, nil
861			}
862		}
863	
864		// exists_one() starts at int(0) and increments via a conditional (predicate ?
865		// accu + 1 : accu) in the loop step.
866		if _, isInt := accuInit.GetConstantKind().(*exprv1.Constant_Int64Value); isInt {
867			if step := comp.LoopStep.GetCallExpr(); step != nil && step.Function == "_?_:_" {
868				return ComprehensionExistsOne, nil
869			}
870		}
871	
872		return "", errors.New("unsupported comprehension type (supported: exists, all, exists_one)")
873	}
874	
875	// extractPredicate extracts the predicate expression from the comprehension loop step.
876	func extractPredicate(comp *exprv1.Expr_Comprehension, _ Schema) (PredicateExpr, error) {
877		// The loop step is: @result || predicate(t) for exists
878		//                or: @result && predicate(t) for all
879		step := comp.LoopStep.GetCallExpr()
880		if step == nil {
881			return nil, errors.New("comprehension loop step must be a call expression")
882		}
883	
884		// exists/all: accu || predicate  /  accu && predicate  -> predicate is arg[1].
885		// exists_one: predicate ? accu + 1 : accu               -> predicate is arg[0].
886		var predicateExpr *exprv1.Expr
887		if step.Function == "_?_:_" {
888			if len(step.Args) != 3 {
889				return nil, errors.New("exists_one loop step must have three arguments")
890			}
891			predicateExpr = step.Args[0]
892		} else {
893			if len(step.Args) != 2 {
894				return nil, errors.New("comprehension loop step must have two arguments")
895			}
896			predicateExpr = step.Args[1]
897		}
898		predicateCall := predicateExpr.GetCallExpr()
899		if predicateCall == nil {
900			return nil, errors.New("comprehension predicate must be a function call")
901		}
902	
903		// Handle different predicate functions
904		switch predicateCall.Function {
905		case "_==_":
906			return buildEqualsPredicate(predicateCall, comp.IterVar)
907		case "startsWith":
908			return buildStartsWithPredicate(predicateCall, comp.IterVar)
909		case "endsWith":
910			return buildEndsWithPredicate(predicateCall, comp.IterVar)
911		case "contains":
912			return buildContainsPredicate(predicateCall, comp.IterVar)
913		default:
914			return nil, errors.Errorf(`unsupported predicate function %q in comprehension (supported: ==, startsWith, endsWith, contains)`, predicateCall.Function)
915		}
916	}
917	
918	// buildEqualsPredicate extracts the value from t == "value".
919	func buildEqualsPredicate(call *exprv1.Expr_Call, iterVar string) (PredicateExpr, error) {
920		if len(call.Args) != 2 {
921			return nil, errors.New("equality predicate expects exactly two arguments")
922		}
923	
924		var constExpr *exprv1.Expr
925		switch {
926		case isIterVarExpr(call.Args[0], iterVar):
927			constExpr = call.Args[1]
928		case isIterVarExpr(call.Args[1], iterVar):
929			constExpr = call.Args[0]
930		default:
931			return nil, errors.Errorf("equality predicate must compare against the iteration variable %q", iterVar)
932		}
933	
934		value, err := getConstValue(constExpr)
935		if err != nil {
936			return nil, errors.Wrap(err, "equality argument must be a constant string")
937		}
938	
939		valueStr, ok := value.(string)
940		if !ok {
941			return nil, errors.New("equality argument must be a string")
942		}
943	
944		return &EqualsPredicate{Value: valueStr}, nil
945	}
946	
947	func isIterVarExpr(expr *exprv1.Expr, iterVar string) bool {
948		target := expr.GetIdentExpr()
949		return target != nil && target.GetName() == iterVar
950	}
951	
952	// buildStartsWithPredicate extracts the pattern from t.startsWith("prefix").
953	func buildStartsWithPredicate(call *exprv1.Expr_Call, iterVar string) (PredicateExpr, error) {
954		// Verify the target is the iteration variable
955		if target := call.Target.GetIdentExpr(); target == nil || target.GetName() != iterVar {
956			return nil, errors.Errorf("startsWith target must be the iteration variable %q", iterVar)
957		}
958	
959		if len(call.Args) != 1 {
960			return nil, errors.New("startsWith expects exactly one argument")
961		}
962	
963		prefix, err := getConstValue(call.Args[0])
964		if err != nil {
965			return nil, errors.Wrap(err, "startsWith argument must be a constant string")
966		}
967	
968		prefixStr, ok := prefix.(string)
969		if !ok {
970			return nil, errors.New("startsWith argument must be a string")
971		}
972	
973		return &StartsWithPredicate{Prefix: prefixStr}, nil
974	}
975	
976	// buildEndsWithPredicate extracts the pattern from t.endsWith("suffix").
977	func buildEndsWithPredicate(call *exprv1.Expr_Call, iterVar string) (PredicateExpr, error) {
978		if target := call.Target.GetIdentExpr(); target == nil || target.GetName() != iterVar {
979			return nil, errors.Errorf("endsWith target must be the iteration variable %q", iterVar)
980		}
981	
982		if len(call.Args) != 1 {
983			return nil, errors.New("endsWith expects exactly one argument")
984		}
985	
986		suffix, err := getConstValue(call.Args[0])
987		if err != nil {
988			return nil, errors.Wrap(err, "endsWith argument must be a constant string")
989		}
990	
991		suffixStr, ok := suffix.(string)
992		if !ok {
993			return nil, errors.New("endsWith argument must be a string")
994		}
995	
996		return &EndsWithPredicate{Suffix: suffixStr}, nil
997	}
998	
999	// buildContainsPredicate extracts the pattern from t.contains("substring").
1000	func buildContainsPredicate(call *exprv1.Expr_Call, iterVar string) (PredicateExpr, error) {
1001		if target := call.Target.GetIdentExpr(); target == nil || target.GetName() != iterVar {
1002			return nil, errors.Errorf("contains target must be the iteration variable %q", iterVar)
1003		}
1004	
1005		if len(call.Args) != 1 {
1006			return nil, errors.New("contains expects exactly one argument")
1007		}
1008	
1009		substring, err := getConstValue(call.Args[0])
1010		if err != nil {
1011			return nil, errors.Wrap(err, "contains argument must be a constant string")
1012		}
1013	
1014		substringStr, ok := substring.(string)
1015		if !ok {
1016			return nil, errors.New("contains argument must be a string")
1017		}
1018	
1019		return &ContainsPredicate{Substring: substringStr}, nil
1020	}
